usage:
import { Particles } from "./Particles";
import "./Particles.css";

<Particles
  shape="Circle"
  reach={80}
  force={60}
  grain="Fine"
/>

notes:
/* ONE SET OF DOTS, MANY SHAPES. Every shape is sampled to the
   same number of points; changing shape only moves each dot's
   home, paired by angle round the middle so the swarm sweeps
   round into the new outline instead of crossing itself. */
homes = sample(shape, 720);

/* the push: away from the pointer, strongest close in */
d.v += away * (1 - dist / reach) ** 2 * force;

/* home on a spring */
d.v = (d.v + (d.home - d.p) * 0.05) * 0.84;

/* press: a shockwave out to 200px, then the next shape */
d.v += away * (1 - dist / 200) * 30;

/* and a moving dot is drawn long along its path */
ctx.ellipse(x, y, r * s, r / sqrt(s), atan2(vy, vx));
